local a={}local function b(c)return c[1][1]*(c[2][2]*c[3][3]-c[2][3]*c[3][2])-c[1][2]*(c[2][1]*c[3][3]-c[2][3]*c[3][1])+c[1][3]*(c[2][1]*c[3][2]-c[2][2]*c[3][1])end;local function d(e,f,g,h)local i,j=e.pos,e.dist;local k=i.x*i.x+i.y*i.y+i.z*i.z;local l,m={},{}local n={f,g,h}for o=1,3 do local p,q=n[o].pos,n[o].dist;l[o]={2*(p.x-i.x),2*(p.y-i.y),2*(p.z-i.z)}local r=p.x*p.x+p.y*p.y+p.z*p.z;m[o]=r-k-(q*q-j*j)end;local s=b(l)if math.abs(s)<1e-9 then return nil end;local function t(u)local c={{l[1][1],l[1][2],l[1][3]},{l[2][1],l[2][2],l[2][3]},{l[3][1],l[3][2],l[3][3]}}c[1][u],c[2][u],c[3][u]=m[1],m[2],m[3]return c end;return{x=b(t(1))/s,y=b(t(2))/s,z=b(t(3))/s}end;local function v(w,x)local y=0;for o=1,#x do local p=x[o].pos;local z,A,B=w.x-p.x,w.y-p.y,w.z-p.z;local C=math.sqrt(z*z+A*A+B*B)-x[o].dist;y=y+C*C end;return y end;function a.solve(x)if type(x)~="table"or#x<4 then return nil end;local D,E;local F=#x;for G=1,F-3 do for m=G+1,F-2 do for H=m+1,F-1 do for C=H+1,F do local w=d(x[G],x[m],x[H],x[C])if w then local I=v(w,x)if not E or I<E then D,E=w,I end end end end end end;return D end;return a